<?php
/* Community, country communities, events, marketplace, mentor, radio, alumni. */
declare(strict_types=1);
$me = require_login(); $uid = $me['uid'];

function blocked_ids(string $uid): array { return array_column(rows('SELECT blocked_uid FROM user_blocks WHERE blocker_uid = ?', [$uid]), 'blocked_uid'); }
function author_of(array $r): string { return (string)($r['uid'] ?: ($r['user_id'] ?? '')); }
function save_image(string $field, string $dir): ?string {
    if (empty($_FILES[$field]['tmp_name']) || $_FILES[$field]['size'] > 4 * 1024 * 1024) return null;
    $info = @getimagesize($_FILES[$field]['tmp_name']); $map = [IMAGETYPE_JPEG => 'jpg', IMAGETYPE_PNG => 'png', IMAGETYPE_WEBP => 'webp'];
    if (!$info || !isset($map[$info[2]])) return null;
    @mkdir(APP_ROOT . "/uploads/$dir", 0755, true); $fn = "uploads/$dir/" . bin2hex(random_bytes(8)) . '.' . $map[$info[2]];
    return move_uploaded_file($_FILES[$field]['tmp_name'], APP_ROOT . '/' . $fn) ? url($fn) : null;
}
function post_card(array $p, array $liked, string $uid, string $where): string {
    $a = ['name' => $p['author_name'], 'avatar_url' => $p['author_avatar'] ?? '']; $body = (string)($p['content'] ?: ($p['body'] ?? '')); $mine = author_of($p) === $uid;
    $h = '<div class="card col" id="p' . e($p['id']) . '"><div class="row">' . avatar($a) . '<div class="grow"><p class="bold">' . e($p['author_name'] ?: 'Member') . (!empty($p['is_admin']) ? ' ' . pill('WODDI team', 'g') : '') . '</p><p class="mut xs">' . ago($p['created_at']) . (!empty($p['category']) ? ', ' . e(ucfirst((string)$p['category'])) : '') . (!empty($p['pinned']) ? ', pinned' : '') . '</p></div>'
        . '<details class="menu"><summary class="ib" aria-label="More">' . ic('fa-ellipsis') . '</summary><form method="post" class="menu-list">' . csrf_field() . '<input type="hidden" name="id" value="' . e($p['id']) . '"><input type="hidden" name="where" value="' . e($where) . '">'
        . ($mine || is_admin() ? '<button name="do" value="delete" data-confirm="Delete this post?">' . ic('fa-trash') . ' Delete</button>' : '')
        . (!$mine ? '<a href="' . url('messages', ['with' => author_of($p)]) . '">' . ic('fa-envelope') . ' Message</a><button name="do" value="report">' . ic('fa-flag') . ' Report</button><button name="do" value="block" data-confirm="Block this member? You will stop seeing her posts.">' . ic('fa-ban') . ' Block member</button>' : '') . '</form></details></div>'
        . (!empty($p['title']) ? '<h3>' . e($p['title']) . '</h3>' : '') . '<p style="white-space:pre-line;overflow-wrap:anywhere">' . e($body) . '</p>' . (!empty($p['image_url']) ? '<img src="' . e($p['image_url']) . '" alt="" loading="lazy" style="border-radius:16px;width:100%;max-height:420px;object-fit:cover">' : '');
    $on = in_array($p['id'], $liked, true); $likes = (int)($p['likes_count'] ?? 0); $com = (int)($p['comments_count'] ?? 0);
    return $h . '<div class="row"><button class="b g s ' . ($on ? 'on' : '') . '" type="button" data-like="' . e($p['id']) . '" data-kind="' . e($where === 'community' ? 'forum' : 'country') . '">' . ic('fa-heart') . ' <span>' . $likes . '</span></button>' . ($where === 'community' ? '<a class="b g s" href="' . url('community', ['post' => $p['id']]) . '">' . ic('fa-comment') . ' ' . $com . '</a>' : '') . '</div></div>';
}

/* ───────── Community ───────── */
if ($first === 'community') {
    $tab = (string)($_GET['tab'] ?? 'feed'); $cc = strtoupper((string)($_GET['c'] ?? ''));
    if (is_post()) {
        $do = post('do'); $id = (string)post('id');
        if ($do === 'post' && trim((string)post('body')) !== '') {
            if (val('SELECT COUNT(*) FROM forum_posts WHERE uid = ? AND created_at > ?', [$uid, gmdate('Y-m-d H:i:s', time() - 60)]) >= 3) { flash('You are posting very fast. Please wait a minute.', 'err'); redirect('community'); }
            $body = mb_substr((string)post('body'), 0, 4000); $img = save_image('image', 'posts');
            if ($cc && val('SELECT 1 FROM country_communities WHERE code = ?', [$cc])) { ins('community_posts', ['country_code' => $cc, 'uid' => $uid, 'author_name' => display_name($me), 'author_avatar' => $me['avatar_url'] ?? '', 'content' => $body, 'image_url' => $img, 'likes_count' => 0, 'comments_count' => 0, 'status' => 'active', 'updated_at' => now()]); redirect('community', ['tab' => 'countries', 'c' => $cc]); }
            ins('forum_posts', ['uid' => $uid, 'user_id' => $uid, 'author_name' => display_name($me), 'author_avatar' => $me['avatar_url'] ?? '', 'content' => $body, 'body' => $body, 'image_url' => $img, 'category' => strtolower((string)post('category', 'general')), 'channel' => net() === 'nnn' ? 'wnnn-community' : 'wgmn-community', 'likes_count' => 0, 'comments_count' => 0, 'status' => 'published', 'is_admin' => is_admin() ? 1 : 0, 'updated_at' => now()]);
            log_event($uid, 'community_post'); redirect('community');
        }
        if ($do === 'comment' && trim((string)post('body')) !== '' && ($p = row('SELECT * FROM forum_posts WHERE id = ?', [$id])) && empty($p['locked'])) {
            ins('forum_comments', ['post_id' => $id, 'uid' => $uid, 'user_id' => $uid, 'author_name' => display_name($me), 'author_avatar' => $me['avatar_url'] ?? '', 'content' => mb_substr((string)post('body'), 0, 2000), 'status' => 'active']);
            q('UPDATE forum_posts SET comments_count = COALESCE(comments_count,0) + 1, comment_count = COALESCE(comment_count,0) + 1, reply_count = COALESCE(reply_count,0) + 1 WHERE id = ?', [$id]);
            if (author_of($p) && author_of($p) !== $uid) notify(author_of($p), first_name($me) . ' replied to your post', mb_strimwidth((string)post('body'), 0, 90, '...'), 'community?post=' . $id, 'comment');
            redirect('community', ['post' => $id]);
        }
        if ($do === 'delete') { $where = post('where') === 'community' ? 'forum_posts' : 'community_posts'; $p = row("SELECT * FROM `$where` WHERE id = ?", [$id]); if ($p && (author_of($p) === $uid || is_admin())) { q("UPDATE `$where` SET status = 'deleted' WHERE id = ?", [$id]); flash('Post deleted.'); } }
        if ($do === 'report') { ins('forum_reports', ['post_id' => $id, 'uid' => $uid, 'reason' => post('reason', 'Reported from the app'), 'status' => 'open']); try { ins('content_reports', ['reporter_uid' => $uid, 'content_type' => 'post', 'content_id' => $id, 'reason' => 'Reported from the app', 'status' => 'open']); } catch (Throwable $e) {} flash('Thank you. The WODDI team will review this post.'); }
        if ($do === 'block') { $where = post('where') === 'community' ? 'forum_posts' : 'community_posts'; $p = row("SELECT * FROM `$where` WHERE id = ?", [$id]); if ($p && author_of($p) !== $uid) { q('INSERT IGNORE INTO user_blocks (blocker_uid, blocked_uid, created_at) VALUES (?,?,?)', [$uid, author_of($p), now()]); flash('Member blocked. You can undo this in Settings.'); } }
        if ($do === 'join' && $cc) { if (!val('SELECT 1 FROM community_members WHERE country_code = ? AND uid = ?', [$cc, $uid])) { ins('community_members', ['country_code' => $cc, 'uid' => $uid, 'role' => 'member', 'status' => 'active', 'joined_at' => now()]); q('UPDATE country_communities SET member_count = COALESCE(member_count,0) + 1 WHERE code = ?', [$cc]); } redirect('community', ['tab' => 'countries', 'c' => $cc]); }
        if ($do === 'rsvp') { q('REPLACE INTO al_rsvps (event_id, uid, status, created_at) VALUES (?,?,?,?)', [$id, $uid, 'going', now()]); flash('You are on the list. We will remind you.'); redirect('community', ['tab' => 'events']); }
        redirect('community', array_filter(['tab' => $tab === 'feed' ? null : $tab, 'c' => $cc ?: null]));
    }
    $blocked = blocked_ids($uid); $notBlocked = fn($r) => !in_array(author_of($r), $blocked, true);
    if ($pid = (string)($_GET['post'] ?? '')) {
        $p = row("SELECT * FROM forum_posts WHERE id = ? AND COALESCE(status,'active') NOT IN ('deleted','hidden')", [$pid]); if (!$p) redirect('community');
        $liked = array_column(rows('SELECT post_id FROM forum_likes WHERE uid = ? AND post_id = ?', [$uid, $pid]), 'post_id');
        $h = '<div class="col" style="gap:14px;max-width:720px;width:100%;margin:0 auto">' . post_card($p, $liked, $uid, 'community') . '<h4>Replies</h4>';
        $cs = array_filter(rows("SELECT * FROM forum_comments WHERE post_id = ? AND COALESCE(status,'active') NOT IN ('deleted','hidden') ORDER BY created_at", [$pid]), $notBlocked);
        foreach ($cs as $c) $h .= '<div class="row rt">' . avatar(['name' => $c['author_name'], 'avatar_url' => $c['author_avatar']], 's') . '<div class="grow" style="background:var(--card);border:1px solid var(--line);border-radius:16px;padding:10px 14px"><p class="bold sm">' . e($c['author_name']) . ' <span class="mut xs" style="font-weight:400">' . ago($c['created_at']) . '</span></p><p style="white-space:pre-line">' . e($c['content']) . '</p></div></div>';
        if (!$cs) $h .= '<p class="mut">Be the first to reply.</p>';
        $h .= empty($p['locked']) ? '<form method="post" class="row">' . csrf_field() . '<input type="hidden" name="do" value="comment"><input type="hidden" name="id" value="' . e($pid) . '"><input class="inp" name="body" required placeholder="Write a reply" autocomplete="off"><button class="ib" style="background:var(--mag);color:#fff" aria-label="Send">' . ic('fa-paper-plane') . '</button></form>' : '<p class="mut sm">Replies are closed on this post.</p>';
        page('Post', $h . '</div>', ['active' => 'community', 'back' => 'community']);
    }
    $h = '<div class="split"><div class="grow col" style="gap:14px;max-width:720px">' . tabs(['feed' => 'Feed', 'countries' => 'Countries', 'events' => 'Events', 'people' => 'Members'], $tab, url('community'));
    $composer = fn(string $ph, string $extra = '') => '<form method="post" enctype="multipart/form-data" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="post">' . $extra . '<div class="row rt">' . avatar($me) . '<textarea class="inp grow" name="body" rows="2" required placeholder="' . e($ph) . '"></textarea></div><div class="row"><label class="b g s">' . ic('fa-image') . ' Photo<input type="file" name="image" accept="image/*" hidden></label><span class="grow"></span><button class="b s">' . ic('fa-paper-plane') . ' Post</button></div></form>';
    if ($tab === 'countries' && $cc && ($c = row('SELECT * FROM country_communities WHERE code = ?', [$cc]))) {
        $member = (bool)val('SELECT 1 FROM community_members WHERE country_code = ? AND uid = ?', [$cc, $uid]);
        $h .= '<div class="hero"><p class="kick">' . e($c['region']) . '</p><h2>' . e(trim($c['flag'] . ' ' . $c['name'])) . '</h2><p class="sm soft">' . (int)$c['member_count'] . ' members</p>' . ($member ? '' : '<form method="post">' . csrf_field() . '<input type="hidden" name="do" value="join"><button class="b l s">' . ic('fa-plus') . ' Join this community</button></form>') . '</div>';
        if ($member) $h .= $composer('Share with women in ' . $c['name']);
        $posts = array_filter(rows("SELECT * FROM community_posts WHERE country_code = ? AND COALESCE(status,'active') NOT IN ('deleted','hidden') ORDER BY pinned DESC, created_at DESC LIMIT 50", [$cc]), $notBlocked);
        $liked = array_column(rows('SELECT post_id FROM community_post_likes WHERE uid = ?', [$uid]), 'post_id');
        foreach ($posts as $p) $h .= post_card($p, $liked, $uid, 'country'); if (!$posts) $h .= empty_state('fa-comments', 'No posts here yet', 'Start the conversation for your country.');
    } elseif ($tab === 'countries') {
        $mine = array_column(rows('SELECT country_code FROM community_members WHERE uid = ?', [$uid]), 'country_code'); $region = '';
        foreach (rows('SELECT * FROM country_communities WHERE COALESCE(is_active,1) = 1 ORDER BY region, name') as $c) { if ($c['region'] !== $region) { if ($region) $h .= '</div>'; $h .= '<h4>' . e($c['region'] ?: 'Other') . '</h4><div class="grp">'; $region = $c['region']; } $h .= '<a class="li" href="' . url('community', ['tab' => 'countries', 'c' => $c['code']]) . '"><span style="font-size:1.5em;width:32px;text-align:center">' . e($c['flag']) . '</span><span class="grow"><span class="bold" style="display:block">' . e($c['name']) . '</span><span class="mut xs">' . (int)$c['member_count'] . ' members</span></span>' . (in_array($c['code'], $mine, true) ? pill('Joined', 'l') : '') . ic('fa-chevron-right', 'mut') . '</a>'; }
        $h .= $region ? '</div>' : empty_state('fa-earth-africa', 'No country communities yet');
    } elseif ($tab === 'events') {
        $going = array_column(rows('SELECT event_id FROM al_rsvps WHERE uid = ?', [$uid]), 'event_id'); $ev = rows("SELECT * FROM al_events WHERE COALESCE(status,'published') NOT IN ('cancelled','draft') AND (starts_at IS NULL OR starts_at > ?) ORDER BY starts_at LIMIT 40", [gmdate('Y-m-d H:i:s', time() - 6 * 3600)]);
        foreach ($ev as $x) $h .= '<div class="card col"><div class="row rt"><div class="cal"><b>' . e($x['starts_at'] ? gmdate('j', strtotime($x['starts_at'])) : '') . '</b>' . e($x['starts_at'] ? gmdate('M', strtotime($x['starts_at'])) : 'TBC') . '</div><div class="grow"><h3>' . e($x['title']) . '</h3><p class="mut sm">' . e($x['starts_at'] ? gmdate('l, g:i A', strtotime($x['starts_at'])) . ' GMT' : 'Date to be confirmed') . ', ' . e($x['mode'] ?: 'Online') . ($x['location'] ? ', ' . e($x['location']) : '') . '</p></div></div><p>' . e($x['description']) . '</p><form method="post" class="row">' . csrf_field() . '<input type="hidden" name="do" value="rsvp"><input type="hidden" name="id" value="' . e($x['id']) . '">' . (in_array($x['id'], $going, true) ? pill('You are going', 'l') : '<button class="b s">' . ic('fa-check') . ' I will attend</button>') . ($x['link'] ? '<a class="b g s" target="_blank" rel="noopener" href="' . e($x['link']) . '">' . ic('fa-video') . ' Join link</a>' : '') . '</form></div>';
        if (!$ev) $h .= empty_state('fa-calendar-days', 'No upcoming events', 'New events from WODDI will show here, and you will get a notification.');
    } elseif ($tab === 'people') {
        $qs = trim((string)($_GET['q'] ?? '')); $h .= '<form class="search" method="get">' . ic('fa-magnifying-glass', 'mut') . '<input type="hidden" name="tab" value="people"><input type="search" name="q" value="' . e($qs) . '" placeholder="Search members by name or country" aria-label="Search members"></form><div class="grp">';
        $p = [$me['pathway'] ?? 'gmn', $uid]; $w = ''; if ($qs !== '') { $w = ' AND (name LIKE ? OR display_name LIKE ? OR country LIKE ?)'; array_push($p, "%$qs%", "%$qs%", "%$qs%"); }
        foreach (rows("SELECT uid, name, display_name, avatar_url, country, profession FROM users WHERE pathway = ? AND uid <> ? AND COALESCE(status,'active') = 'active'$w ORDER BY last_seen DESC LIMIT 40", $p) as $u) if (!in_array($u['uid'], $blocked, true)) $h .= '<a class="li" href="' . url('messages', ['with' => $u['uid']]) . '">' . avatar($u) . '<span class="grow"><span class="bold" style="display:block">' . e(display_name($u)) . '</span><span class="mut xs">' . e(implode(', ', array_filter([$u['profession'], $u['country']]))) . '</span></span>' . ic('fa-envelope', 'mut') . '</a>';
        $h .= '</div>';
    } else {
        $cat = (string)($_GET['cat'] ?? ''); $h .= $composer('Share a win, ask a question, encourage someone', '<input type="hidden" name="category" value="' . e($cat ?: 'general') . '">') . '<div class="chips">';
        foreach (['' => 'All', 'general' => 'General', 'inspiration' => 'Inspiration', 'questions' => 'Questions', 'wins' => 'Wins', 'business' => 'Business'] as $k => $lab) $h .= '<a class="chip ' . ($cat === $k ? 'on' : '') . '" href="' . url('community', $k ? ['cat' => $k] : []) . '">' . $lab . '</a>';
        $h .= '</div>'; $p = [net() === 'nnn' ? 'wnnn-community' : 'wgmn-community']; $w = ''; if ($cat) { $w = ' AND category = ?'; $p[] = $cat; }
        $posts = array_filter(rows("SELECT * FROM forum_posts WHERE COALESCE(status,'active') NOT IN ('deleted','hidden') AND COALESCE(hidden,0) = 0 AND (channel IS NULL OR channel IN ('', 'all', ?))$w ORDER BY pinned DESC, created_at DESC LIMIT 60", $p), $notBlocked);
        $liked = array_column(rows('SELECT post_id FROM forum_likes WHERE uid = ?', [$uid]), 'post_id');
        foreach ($posts as $p) $h .= post_card($p, $liked, $uid, 'community'); if (!$posts) $h .= empty_state('fa-comments', 'No posts yet', 'Be the first to say hello to your network.');
    }
    $h .= '</div><div class="aside"><div class="card col"><h4>Community promise</h4><p class="mut sm">Be kind. No selling in the feed (use the Marketplace). No sharing of private details. Report anything that worries you.</p></div><div class="card col"><h4>Your network</h4><p class="bold">' . e(net_name()) . '</p><p class="mut sm">' . (int)val("SELECT COUNT(*) FROM users WHERE pathway = ?", [$me['pathway'] ?? 'gmn']) . ' members</p></div></div></div>';
    page('Community', $h, ['active' => 'community']);
}

/* ───────── Marketplace ───────── */
if ($first === 'market') {
    $rules = points_rules(); $tab = (string)($_GET['tab'] ?? 'browse'); $cats = ['handmade', 'digital', 'fashion', 'food', 'beauty', 'services', 'farm produce', 'training', 'other']; $certified = (bool)val('SELECT 1 FROM certificates WHERE uid = ? AND COALESCE(revoked,0) = 0 LIMIT 1', [$uid]);
    if (is_post()) {
        $do = post('do'); $id = (string)post('id'); $L = $id ? row('SELECT * FROM mp_listings WHERE id = ?', [$id]) : null; $own = $L && $L['user_id'] === $uid;
        if ($do === 'save') {
            $d = ['title' => mb_substr((string)post('title'), 0, 120), 'description' => mb_substr((string)post('description'), 0, 3000), 'listing_type' => post('listing_type', 'product'), 'category' => post('category', 'Other'), 'price' => (float)post('price', '0'), 'currency' => mb_substr((string)post('currency', 'NGN'), 0, 5), 'price_type' => post('price_type', 'fixed'), 'delivery' => mb_substr((string)post('delivery'), 0, 200), 'country' => post('country', $me['country'] ?? ''), 'city' => post('city', $me['city'] ?? ''), 'whatsapp' => preg_replace('/[^0-9+]/', '', (string)post('whatsapp')), 'updated_at' => now()];
            if ($d['title'] === '') { flash('Give your listing a title.', 'err'); redirect('market', ['tab' => 'shop']); }
            if ($img = save_image('image', 'market')) { $d['image_url'] = $img; $d['images'] = [$img]; }
            if ($own) upd('mp_listings', $d, 'id = ?', [$id]); else ins('mp_listings', $d + ['user_id' => $uid, 'seller_name' => display_name($me), 'seller_avatar' => $me['avatar_url'] ?? '', 'status' => $certified ? 'active' : 'pending_certificate', 'sold' => 0, 'views' => 0, 'enquiries' => 0, 'featured' => 0, 'published_at' => now()]);
            flash($certified || $own ? 'Listing saved.' : 'Listing saved. It goes live by itself as soon as you earn your first certificate.'); redirect('market', ['tab' => 'shop']);
        }
        if ($own && $do === 'sold') { upd('mp_listings', ['sold' => empty($L['sold']) ? 1 : 0, 'sold_at' => now()], 'id = ?', [$id]); }
        if ($own && $do === 'pause' && in_array($L['status'], ['active', 'paused'], true)) upd('mp_listings', ['status' => $L['status'] === 'paused' ? 'active' : 'paused'], 'id = ?', [$id]);
        if ($own && $do === 'remove') { upd('mp_listings', ['status' => 'removed'], 'id = ?', [$id]); flash('Listing removed.'); }
        if ($own && $do === 'boost' && $L['status'] !== 'active') flash('Only a live listing can be boosted.', 'err');
        elseif ($own && $do === 'boost') { $cost = (int)$rules['market_boost_cost']; if (points($uid) < $cost) flash('You need ' . $cost . ' Growth Points to boost a listing.', 'err'); else { award($uid, -$cost, 'boost:' . $id . ':' . time()); upd('mp_listings', ['boost_until' => gmdate('Y-m-d H:i:s', time() + 7 * 86400), 'featured' => 1], 'id = ?', [$id]); flash('Boosted for 7 days. Your listing now shows first.'); } }
        if ($do === 'enquire' && $L && !$own) {
            ins('mp_enquiries', ['item_id' => $id, 'seller_id' => $L['user_id'], 'buyer_uid' => $uid, 'buyer_name' => display_name($me), 'buyer_contact' => post('contact', $me['phone'] ?? ''), 'kind' => 'enquiry', 'quantity' => post('quantity', '1'), 'message' => mb_substr((string)post('message'), 0, 1500), 'status' => 'new', 'review_token' => bin2hex(random_bytes(12)), 'updated_at' => now()]);
            q('UPDATE mp_listings SET enquiries = COALESCE(enquiries,0) + 1 WHERE id = ?', [$id]); notify($L['user_id'], 'New enquiry on ' . $L['title'], first_name($me) . ': ' . mb_strimwidth((string)post('message'), 0, 80, '...'), 'market?tab=shop', 'market'); flash('Enquiry sent to the seller.'); redirect('market', ['item' => $id]);
        }
        if ($do === 'enq-status' && ($q = row('SELECT * FROM mp_enquiries WHERE id = ? AND seller_id = ?', [$id, $uid]))) { upd('mp_enquiries', ['status' => post('status', 'replied'), 'seller_note' => mb_substr((string)post('note'), 0, 500), 'updated_at' => now()], 'id = ?', [$id]); notify($q['buyer_uid'], 'The seller replied to your enquiry', (string)post('note'), 'market?tab=orders', 'market'); }
        if ($do === 'review' && $L && !$own && val('SELECT 1 FROM mp_enquiries WHERE item_id = ? AND buyer_uid = ?', [$id, $uid]) && !val('SELECT 1 FROM mp_reviews WHERE item_id = ? AND reviewer_uid = ?', [$id, $uid])) {
            $r = max(1, min(5, (int)post('rating', '5'))); ins('mp_reviews', ['item_id' => $id, 'seller_id' => $L['user_id'], 'reviewer_uid' => $uid, 'reviewer_name' => display_name($me), 'rating' => $r, 'comment' => mb_substr((string)post('comment'), 0, 1000), 'verified' => 1, 'status' => 'published']);
            $agg = row("SELECT AVG(rating) a, COUNT(*) c FROM mp_reviews WHERE item_id = ? AND status = 'published'", [$id]); upd('mp_listings', ['rating_avg' => round((float)$agg['a'], 2), 'rating_count' => (int)$agg['c']], 'id = ?', [$id]); redirect('market', ['item' => $id]);
        }
        if ($do === 'report' && $L) { try { ins('content_reports', ['reporter_uid' => $uid, 'content_type' => 'listing', 'content_id' => $id, 'reported_uid' => $L['user_id'], 'reason' => post('reason', 'Reported from the app'), 'status' => 'open']); } catch (Throwable $e) {} flash('Thank you. The WODDI team will review this listing.'); redirect('market', ['item' => $id]); }
        redirect('market', ['tab' => $tab]);
    }
    $money = fn($L) => ($L['price_type'] ?? '') === 'negotiable' && !(float)$L['price'] ? 'Negotiable' : (((float)$L['price']) ? e($L['currency'] ?: 'NGN') . ' ' . number_format((float)$L['price']) : 'Ask for price');
    $thumb = fn($L, $h = 150) => !empty($L['image_url']) ? '<img src="' . e($L['image_url']) . '" alt="" loading="lazy" style="width:100%;height:' . $h . 'px;object-fit:cover;border-radius:14px">' : '<div style="height:' . $h . 'px;border-radius:14px;background:var(--mags);display:flex;align-items:center;justify-content:center;color:var(--magt);font-size:30px">' . ic(($L['listing_type'] ?? '') === 'service' ? 'fa-handshake' : 'fa-bag-shopping') . '</div>';
    if ($iid = (string)($_GET['item'] ?? '')) {
        $L = row("SELECT * FROM mp_listings WHERE id = ? AND (COALESCE(status,'active') = 'active' OR user_id = ?)", [$iid, $uid]); if (!$L || $L['status'] === 'removed') redirect('market');
        if ($L['user_id'] !== $uid) q('UPDATE mp_listings SET views = COALESCE(views,0) + 1 WHERE id = ?', [$iid]);
