/* ───────── Mentor ───────── */
function mentor_reply(array $me, array $history, string $text): array {
    $j = journey($me['uid']); $ctx = 'Learner: ' . first_name($me) . ', ' . net_name() . ', ' . ($me['country'] ?? 'Africa') . '. Rooting ' . count($j['rooting']) . '/' . $j['root_total'] . ', Blueprint ' . $j['blue_n'] . '/' . $j['blue_total'] . '. Language: ' . (COURSE_LANGS[$me['language'] ?? 'en'] ?? 'English') . '.';
    $sys = "You are WADI, the WODDI Institute AI mentor for women in Africa. Be warm, practical and brief (under 160 words). Use simple words. Give one clear next step. Reply in the learner's language. You are not a doctor, lawyer or counsellor: for health, legal or safety emergencies tell her to contact a local professional or WODDI Support. Never invent WODDI policies. $ctx";
    $t0 = microtime(true);
    if ($key = cfg('gemini_key')) {
        $contents = []; foreach ($history as $m) $contents[] = ['role' => $m['role'] === 'assistant' ? 'model' : 'user', 'parts' => [['text' => (string)$m['content']]]]; $contents[] = ['role' => 'user', 'parts' => [['text' => $text]]];
        $model = cfg('gemini_model', 'gemini-2.0-flash'); $r = http_json("https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=" . rawurlencode($key), ['system_instruction' => ['parts' => [['text' => $sys]]], 'contents' => $contents, 'generationConfig' => ['temperature' => 0.6, 'maxOutputTokens' => 500]]);
        $out = $r['body']['candidates'][0]['content']['parts'][0]['text'] ?? null; if ($out) return [trim($out), 'gemini', $model, (int)((microtime(true) - $t0) * 1000)];
    }
    if ($key = cfg('openai_key')) {
        $msgs = [['role' => 'system', 'content' => $sys]]; foreach ($history as $m) $msgs[] = ['role' => $m['role'] === 'assistant' ? 'assistant' : 'user', 'content' => (string)$m['content']]; $msgs[] = ['role' => 'user', 'content' => $text];
        $r = http_json('https://api.openai.com/v1/chat/completions', ['model' => cfg('openai_model', 'gpt-4o-mini'), 'messages' => $msgs, 'max_tokens' => 500], ['Authorization: Bearer ' . $key]); $out = $r['body']['choices'][0]['message']['content'] ?? null; if ($out) return [trim($out), 'openai', cfg('openai_model', 'gpt-4o-mini'), (int)((microtime(true) - $t0) * 1000)];
    }
    try { ins('ai_mentor_failures', ['uid' => $me['uid'], 'kind' => cfg('gemini_key') || cfg('openai_key') ? 'provider_error' : 'no_key', 'message' => mb_substr($text, 0, 200)]); } catch (Throwable $e) {}
    $next = !$j['root_done'] ? 'Your next step is the Rooting Phase. Open My Journey and continue from where you stopped.' : (!$j['hub_open'] ? 'Your next step is the Blueprint. Open My Journey to continue.' : 'The Course Hub is open to you. Pick one course and finish its first module this week.');
    return ["I cannot reach my full mentor brain right now, so here is the simple answer. $next If you need a person, tap Human mentors above and send a request, or open Support.", 'fallback', 'none', 0];
}
if ($first === 'mentor') {
    $tab = (string)($_GET['tab'] ?? 'chat');
    if (is_post()) {
        $do = post('do');
        if ($do === 'ask' && ($text = mb_substr((string)post('body'), 0, 2000)) !== '') {
            if (val('SELECT COUNT(*) FROM ai_mentor_messages WHERE uid = ? AND role = ? AND created_at > ?', [$uid, 'user', gmdate('Y-m-d H:i:s', time() - 3600)]) >= 40) { flash('You have asked many questions this hour. Take a short break and come back.', 'err'); redirect('mentor'); }
            $tid = (string)post('t'); if (!$tid || !val('SELECT 1 FROM ai_mentor_threads WHERE id = ? AND uid = ?', [$tid, $uid])) $tid = (string)ins('ai_mentor_threads', ['uid' => $uid, 'title' => mb_strimwidth($text, 0, 60, '...'), 'topic' => 'general', 'message_count' => 0, 'archived' => 0, 'updated_at' => now()]);
            $hist = array_reverse(rows('SELECT role, content FROM ai_mentor_messages WHERE thread_id = ? ORDER BY created_at DESC LIMIT 12', [$tid]));
            ins('ai_mentor_messages', ['thread_id' => $tid, 'uid' => $uid, 'role' => 'user', 'content' => $text]);
            [$out, $engine, $model, $ms] = mentor_reply($me, $hist, $text);
