            q('UPDATE ai_mentor_threads SET message_count = COALESCE(message_count,0) + 2, updated_at = ? WHERE id = ?', [now(), $tid]); log_event($uid, 'mentor_chat'); redirect('mentor', ['t' => $tid]);
