        redirect('mentor');
    }
    $h = '<div class="col" style="gap:14px;max-width:760px;width:100%;margin:0 auto"><div class="card row"><img src="' . asset('woddi-ai-mentor-character.png') . '" alt="" style="width:56px;height:56px;border-radius:50%;object-fit:cover;background:var(--mags)"><div class="grow"><h2>WADI, your mentor</h2><p class="mut sm">Ask about your courses, your business or your next step. In any of the 8 languages.</p></div></div>' . tabs(['chat' => 'Ask WADI', 'human' => 'Human mentors', 'plan' => 'My plan'], $tab, url('mentor'));
    if ($tab === 'human') {
