        foreach ($ms as $m) $h .= '<form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="request"><input type="hidden" name="mentor" value="' . e($m['id']) . '"><div class="row">' . avatar($m) . '<div class="grow"><p class="bold">' . e($m['name']) . '</p><p class="mut sm">' . e($m['title']) . '</p></div></div><p class="sm">' . e(is_array($x = jdec($m['expertise'], null)) ? implode(', ', $x) : $m['expertise']) . '</p><input class="inp" name="area" placeholder="What do you need help with?" required><textarea class="inp" name="message" rows="2" placeholder="Tell her a little about your situation"></textarea><button class="b s" style="align-self:flex-start">' . ic('fa-handshake') . ' Request this mentor</button></form>';
        if (!$ms) $h .= '<form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="request"><h3>Ask for a human mentor</h3><input class="inp" name="area" placeholder="What do you need help with?" required><textarea class="inp" name="message" rows="3" placeholder="Tell us a little about your situation"></textarea><button class="b s" style="align-self:flex-start">Send request</button></form>';
        $mine = rows('SELECT * FROM mentor_requests WHERE uid = ? OR student_uid = ? ORDER BY created_at DESC LIMIT 10', [$uid, $uid]);
        if ($mine) { $h .= '<h4>My requests</h4><div class="grp">'; foreach ($mine as $r) $h .= '<div class="li"><span class="grow"><span class="bold" style="display:block">' . e($r['area'] ?: $r['topic']) . '</span><span class="mut xs">' . e($r['mentor_display_name'] ?: 'Any mentor') . ', ' . ago($r['created_at']) . '</span></span>' . (in_array($r['status'], ['accepted', 'matched'], true) && $r['whatsapp_url'] ? '<a class="b l s" target="_blank" rel="noopener" href="' . e($r['whatsapp_url']) . '"><i class="fa-brands fa-whatsapp"></i></a>' : '') . pill(ucfirst((string)$r['status']), in_array($r['status'], ['accepted', 'matched'], true) ? 'l' : 'n') . '</div>'; $h .= '</div>'; }
    } elseif ($tab === 'plan') {
        $p = row('SELECT * FROM mentor_profiles WHERE uid = ?', [$uid]) ?: []; $sel = fn($n, $opts, $cur) => '<select class="inp" name="' . $n . '">' . implode('', array_map(fn($o) => '<option' . ($o === $cur ? ' selected' : '') . '>' . $o . '</option>', $opts)) . '</select>';
        $h .= '<form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="profile"><h3>My learning plan</h3><label class="fld">My main goal<input class="inp" name="goal" value="' . e($p['goal'] ?? '') . '" placeholder="For example: start selling my products online"></label><div class="g2"><label class="fld">My level' . $sel('level', ['Beginner', 'Intermediate', 'Advanced'], $p['level'] ?? 'Beginner') . '</label><label class="fld">Hours I can learn each week<input class="inp" type="number" min="1" max="40" name="hours" value="' . e($p['hours_per_week'] ?? 3) . '"></label><label class="fld">How I like to learn' . $sel('style', ['Reading', 'Video', 'Listening', 'Doing'], $p['style'] ?? 'Video') . '</label><label class="fld">What keeps me going<input class="inp" name="motivation" value="' . e($p['motivation'] ?? '') . '"></label></div><button class="b s" style="align-self:flex-start">Save my plan</button></form>';
