        $tid = (string)($_GET['t'] ?? ''); if (!$tid && empty($_GET['new'])) $tid = (string)val('SELECT id FROM ai_mentor_threads WHERE uid = ? AND COALESCE(archived,0) = 0 ORDER BY updated_at DESC LIMIT 1', [$uid]);
        $msgs = $tid ? rows('SELECT * FROM ai_mentor_messages WHERE thread_id = ? AND uid = ? ORDER BY created_at, role DESC', [$tid, $uid]) : [];
        $h .= '<div class="row jb"><a class="b g s" href="' . url('mentor', ['new' => 1]) . '">' . ic('fa-plus') . ' New chat</a><details class="menu"><summary class="b g s">' . ic('fa-clock-rotate-left') . ' Past chats</summary><div class="menu-list">'; foreach (rows('SELECT id, title FROM ai_mentor_threads WHERE uid = ? ORDER BY updated_at DESC LIMIT 12', [$uid]) as $t) $h .= '<a href="' . url('mentor', ['t' => $t['id']]) . '">' . e($t['title'] ?: 'Chat') . '</a>'; $h .= '</div></details></div><div class="col" style="gap:8px">';
        if (!$msgs) { $h .= '<div class="bub">Hello ' . e(first_name($me)) . '. I am WADI. What would you like help with today?</div><div class="chips">'; foreach (['What should I learn next?', 'Help me plan my week', 'How do I price my product?', 'I feel stuck in my course'] as $s) $h .= '<form method="post">' . csrf_field() . '<input type="hidden" name="do" value="ask"><input type="hidden" name="body" value="' . e($s) . '"><button class="chip">' . $s . '</button></form>'; $h .= '</div>'; }
        foreach ($msgs as $m) $h .= '<div class="bub ' . ($m['role'] === 'user' ? 'me' : '') . '" style="white-space:pre-line">' . preg_replace('/\*\*([^*]+)\*\*/', '<strong>$1</strong>', e($m['content'])) . '</div>';
        $h .= '</div><form method="post" class="row" id="ask">' . csrf_field() . '<input type="hidden" name="do" value="ask"><input type="hidden" name="t" value="' . e($tid) . '"><input class="inp" name="body" required maxlength="2000" placeholder="Ask WADI anything" autocomplete="off"><button class="ib" style="background:var(--mag);color:#fff" aria-label="Send">' . ic('fa-paper-plane') . '</button></form><p class="xs mut">WADI is an AI guide. It can be wrong. For health, legal or safety matters, speak to a professional.</p>';
    }
    page('Mentor', $h . '</div>', ['active' => 'mentor', 'foot' => '<script>var a=document.getElementById("ask");if(a){a.scrollIntoView({block:"end"});a.addEventListener("submit",function(){a.querySelector("button").disabled=true;a.querySelector("button").innerHTML="<i class=\\"fa-solid fa-spinner fa-spin\\"></i>";});}</script>']);
}

/* ───────── Radio ───────── */
if ($first === 'radio') {
    $progs = rows('SELECT * FROM radio_programs WHERE COALESCE(published,1) = 1 ORDER BY order_index, name'); $eps = rows('SELECT * FROM radio WHERE COALESCE(published,1) = 1 ORDER BY created_at DESC LIMIT 40');
    $h = '<div class="col" style="gap:16px;max-width:860px;width:100%;margin:0 auto"><div class="hero"><p class="kick">WODDI Radio</p><h2>Listen while you work</h2><p class="sm soft">Talks, teaching and encouragement for women. Audio uses far less data than video.</p></div>';
    foreach ($progs as $p) $h .= '<div class="card col"><div class="row"><span class="ic p" style="background:' . e($p['cover_color'] ?: 'var(--mags)') . ';color:#fff;font-weight:800">' . e($p['icon_text'] ?: mb_substr((string)$p['short_name'], 0, 2)) . '</span><div class="grow"><h3>' . e($p['name']) . '</h3><p class="mut sm">' . e($p['tagline']) . '</p></div>' . pill($p['category'] ?: 'Live', 'n') . '</div><p class="sm">' . e($p['description']) . '</p>' . ($p['stream_url'] ? '<audio controls preload="none" style="width:100%" src="' . e($p['stream_url']) . '"></audio>' : '<p class="mut sm">This programme is not on air right now.</p>') . '</div>';
    if ($eps) { $h .= '<h3>Episodes</h3>'; foreach ($eps as $x) $h .= '<div class="card col"><p class="bold">' . e($x['title']) . '</p><p class="mut sm">' . e($x['description']) . '</p><audio controls preload="none" style="width:100%" src="' . e($x['audio_url']) . '"></audio></div>'; }
    if (!$progs && !$eps) $h .= empty_state('fa-radio', 'Nothing on air yet', 'New programmes will show here.');
    page('Radio', $h . '</div>', ['active' => 'radio']);
}

/* ───────── Alumni ───────── */
if ($first === 'alumni') {
    $certN = (int)val('SELECT COUNT(*) FROM certificates WHERE uid = ? AND COALESCE(revoked,0) = 0', [$uid]);
    if (!$certN && !is_staff()) page('Alumni', '<div style="max-width:620px;margin:0 auto;width:100%">' . empty_state('fa-user-graduate', 'The Alumni Network opens with your first certificate', 'Finish any course and pass its final assessment. You will then join circles, see opportunities and meet other graduates.', '<a class="b" href="' . url('learn') . '">Open the Course Hub</a>') . '</div>', ['active' => 'alumni']);
    $tab = (string)($_GET['tab'] ?? 'feed');
    if (is_post()) {
        $do = post('do'); $id = (string)post('id');
        if ($do === 'post' && trim((string)post('body')) !== '') ins('al_posts', ['author' => $uid, 'circle_id' => post('circle') ?: null, 'kind' => post('kind', 'update'), 'body' => mb_substr((string)post('body'), 0, 4000), 'link' => filter_var(post('link'), FILTER_VALIDATE_URL) ?: null, 'pinned' => 0, 'status' => 'published', 'comment_count' => 0, 'reaction_count' => 0]);
        if ($do === 'comment' && trim((string)post('body')) !== '') { ins('al_comments', ['post_id' => $id, 'author' => $uid, 'body' => mb_substr((string)post('body'), 0, 2000), 'status' => 'published']); q('UPDATE al_posts SET comment_count = COALESCE(comment_count,0) + 1 WHERE id = ?', [$id]); }
        if ($do === 'react') { if (val('SELECT 1 FROM al_reactions WHERE post_id = ? AND uid = ?', [$id, $uid])) { q('DELETE FROM al_reactions WHERE post_id = ? AND uid = ?', [$id, $uid]); q('UPDATE al_posts SET reaction_count = GREATEST(COALESCE(reaction_count,0) - 1, 0) WHERE id = ?', [$id]); } else { q('INSERT INTO al_reactions (post_id, uid, kind, created_at) VALUES (?,?,?,?)', [$id, $uid, 'cheer', now()]); q('UPDATE al_posts SET reaction_count = COALESCE(reaction_count,0) + 1 WHERE id = ?', [$id]); } }
        if ($do === 'join') { q('INSERT IGNORE INTO al_circle_members (circle_id, uid, joined_at) VALUES (?,?,?)', [$id, $uid, now()]); }
        if ($do === 'leave') { q('DELETE FROM al_circle_members WHERE circle_id = ? AND uid = ?', [$id, $uid]); }
        if ($do === 'profile') q('REPLACE INTO al_profiles (uid, headline, bio, skills, open_to, location, linkedin, contact, contact_visible, show_in_directory, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)', [$uid, mb_substr((string)post('headline'), 0, 160), mb_substr((string)post('bio'), 0, 1500), json_encode(array_values(array_filter(array_map('trim', explode(',', (string)post('skills')))))), json_encode(array_values(array_filter(array_map('trim', explode(',', (string)post('open_to')))))), post('location'), post('linkedin'), post('contact'), post('contact_visible') ? 1 : 0, post('show') ? 1 : 0, now()]);
        if ($do === 'opp' && trim((string)post('title')) !== '') ins('al_opportunities', ['author' => $uid, 'title' => mb_substr((string)post('title'), 0, 160), 'kind' => post('kind', 'job'), 'organisation' => post('organisation'), 'location' => post('location'), 'remote' => post('remote') ? 1 : 0, 'deadline' => post('deadline') ?: null, 'link' => filter_var(post('link'), FILTER_VALIDATE_URL) ?: null, 'description' => mb_substr((string)post('description'), 0, 3000), 'status' => 'published']);
        redirect('alumni', ['tab' => $tab]);
    }
    $list = fn($v) => implode(', ', (array)jdec($v, []));
    $h = '<div class="col" style="gap:14px;max-width:760px;width:100%;margin:0 auto">' . tabs(['feed' => 'Feed', 'circles' => 'Circles', 'people' => 'Directory', 'opps' => 'Opportunities', 'me' => 'My card'], $tab, url('alumni'));
    if ($tab === 'circles') {
        $mine = array_column(rows('SELECT circle_id FROM al_circle_members WHERE uid = ?', [$uid]), 'circle_id');
        foreach (rows('SELECT c.*, (SELECT COUNT(*) FROM al_circle_members m WHERE m.circle_id = c.id) n FROM al_circles c ORDER BY name') as $c) $h .= '<form method="post" class="card row">' . csrf_field() . '<input type="hidden" name="id" value="' . e($c['id']) . '"><span class="ic p">' . ic(str_starts_with((string)$c['icon'], 'fa-') ? $c['icon'] : 'fa-people-group') . '</span><div class="grow"><p class="bold">' . e($c['name']) . '</p><p class="mut sm">' . e($c['description']) . '</p><p class="xs mut">' . (int)$c['n'] . ' members</p></div>' . (in_array($c['id'], $mine, true) ? '<button class="b g s" name="do" value="leave">Leave</button>' : '<button class="b s" name="do" value="join">Join</button>') . '</form>';
    } elseif ($tab === 'people') {
        foreach (rows('SELECT p.*, u.name, u.display_name, u.avatar_url FROM al_profiles p JOIN users u ON u.uid = p.uid WHERE COALESCE(p.show_in_directory,1) = 1 ORDER BY p.updated_at DESC LIMIT 60') as $p) $h .= '<div class="card row rt">' . avatar($p) . '<div class="grow"><p class="bold">' . e(display_name($p)) . '</p><p class="sm">' . e($p['headline']) . '</p><p class="mut xs">' . e($p['location']) . ($list($p['skills']) ? ', ' . e($list($p['skills'])) : '') . '</p>' . (!empty($p['contact_visible']) && $p['contact'] ? '<p class="xs">' . e($p['contact']) . '</p>' : '') . '</div><a class="ib" href="' . url('messages', ['with' => $p['uid']]) . '" aria-label="Message">' . ic('fa-envelope') . '</a></div>';
        if (!str_contains($h, 'card row rt')) $h .= empty_state('fa-address-book', 'The directory is just starting', 'Fill in My card to be the first.');
    } elseif ($tab === 'opps') {
        $h .= '<details class="card"><summary class="bold">' . ic('fa-plus') . ' Share an opportunity</summary><form method="post" class="col" style="margin-top:12px">' . csrf_field() . '<input type="hidden" name="do" value="opp"><input class="inp" name="title" required placeholder="Title"><div class="g2"><select class="inp" name="kind"><option value="job">Job</option><option value="grant">Grant</option><option value="training">Training</option><option value="volunteer">Volunteer</option></select><input class="inp" name="organisation" placeholder="Organisation"><input class="inp" name="location" placeholder="Location"><input class="inp" type="date" name="deadline" aria-label="Deadline"></div><input class="inp" type="url" name="link" placeholder="Link, starting with https://"><textarea class="inp" name="description" rows="3" placeholder="Details"></textarea><button class="b s" style="align-self:flex-start">Share</button></form></details>';
        $o = rows("SELECT * FROM al_opportunities WHERE COALESCE(status,'published') = 'published' AND (deadline IS NULL OR deadline >= CURDATE()) ORDER BY created_at DESC LIMIT 40");
        foreach ($o as $x) $h .= '<div class="card col"><div class="row jb"><h3>' . e($x['title']) . '</h3>' . pill(ucfirst((string)$x['kind']), 'n') . '</div><p class="mut sm">' . e(implode(', ', array_filter([$x['organisation'], $x['location'], $x['deadline'] ? 'closes ' . gmdate('j M Y', strtotime($x['deadline'])) : '']))) . '</p><p style="white-space:pre-line">' . e($x['description']) . '</p>' . ($x['link'] ? '<a class="b g s" style="align-self:flex-start" target="_blank" rel="noopener" href="' . e($x['link']) . '">Open ' . ic('fa-arrow-up-right-from-square') . '</a>' : '') . '</div>'; if (!$o) $h .= empty_state('fa-briefcase', 'No open opportunities right now');
    } elseif ($tab === 'me') {
        $p = row('SELECT * FROM al_profiles WHERE uid = ?', [$uid]) ?: [];
        $h .= '<form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="profile"><h3>My alumni card</h3><label class="fld">Headline<input class="inp" name="headline" value="' . e($p['headline'] ?? '') . '" placeholder="For example: Baker and digital skills trainer"></label><label class="fld">About me<textarea class="inp" name="bio" rows="3">' . e($p['bio'] ?? '') . '</textarea></label><div class="g2"><label class="fld">Skills, separated by commas<input class="inp" name="skills" value="' . e($list($p['skills'] ?? '')) . '"></label><label class="fld">Open to<input class="inp" name="open_to" value="' . e($list($p['open_to'] ?? '')) . '" placeholder="Mentoring, jobs, partnerships"></label><label class="fld">Location<input class="inp" name="location" value="' . e($p['location'] ?? ($me['country'] ?? '')) . '"></label><label class="fld">LinkedIn<input class="inp" name="linkedin" value="' . e($p['linkedin'] ?? '') . '"></label></div><label class="fld">Contact<input class="inp" name="contact" value="' . e($p['contact'] ?? '') . '"></label><label class="row"><input class="sw" type="checkbox" name="contact_visible" value="1"' . (!empty($p['contact_visible']) ? ' checked' : '') . '><span>Show my contact to other alumni</span></label><label class="row"><input class="sw" type="checkbox" name="show" value="1"' . (!isset($p['show_in_directory']) || $p['show_in_directory'] ? ' checked' : '') . '><span>Show me in the directory</span></label><button class="b s" style="align-self:flex-start">Save my card</button></form>';
    } else {
        $h .= '<form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="post"><textarea class="inp" name="body" rows="2" required placeholder="Share an update, a win or a question with other graduates"></textarea><div class="row"><select class="inp" name="kind" style="width:auto"><option value="update">Update</option><option value="win">Win</option><option value="question">Question</option></select><span class="grow"></span><button class="b s">Post</button></div></form>';
        $mineR = array_column(rows('SELECT post_id FROM al_reactions WHERE uid = ?', [$uid]), 'post_id');
        $posts = rows("SELECT p.*, u.name, u.display_name, u.avatar_url FROM al_posts p LEFT JOIN users u ON u.uid = p.author WHERE COALESCE(p.status,'published') = 'published' ORDER BY p.pinned DESC, p.created_at DESC LIMIT 40");
        foreach ($posts as $p) { $h .= '<div class="card col"><div class="row">' . avatar($p) . '<div class="grow"><p class="bold">' . e(display_name($p)) . '</p><p class="mut xs">' . ago($p['created_at']) . ', ' . e($p['kind']) . '</p></div></div><p style="white-space:pre-line">' . e($p['body']) . '</p>' . ($p['link'] ? '<a class="sm" style="color:var(--magt)" target="_blank" rel="noopener" href="' . e($p['link']) . '">' . e($p['link']) . '</a>' : '');
            foreach (rows("SELECT c.*, u.name, u.display_name FROM al_comments c LEFT JOIN users u ON u.uid = c.author WHERE c.post_id = ? AND COALESCE(c.status,'published') = 'published' ORDER BY c.created_at LIMIT 20", [$p['id']]) as $c) $h .= '<p class="sm" style="background:var(--bg);border-radius:12px;padding:8px 12px"><strong>' . e(display_name($c)) . '</strong> ' . e($c['body']) . '</p>';
            $h .= '<form method="post" class="row">' . csrf_field() . '<input type="hidden" name="id" value="' . e($p['id']) . '"><button class="b g s ' . (in_array($p['id'], $mineR, true) ? 'on' : '') . '" name="do" value="react" formnovalidate>' . ic('fa-hands-clapping') . ' ' . (int)$p['reaction_count'] . '</button><input class="inp" name="body" placeholder="Reply" autocomplete="off"><button class="b g s" name="do" value="comment">Send</button></form></div>'; }
        if (!$posts) $h .= empty_state('fa-user-graduate', 'No alumni posts yet', 'Say hello to your fellow graduates.');
    }
    page('Alumni', $h . '</div>', ['active' => 'alumni']);
}
